#!/usr/bin/env python3
"""Freeze gzip streams made by CPython's zlib, with their expected output, to validate ECDEV's gunzip.

Usage: python3 gzip_oracle.py > fixture.json
Cases cover every DEFLATE block type (stored, fixed Huffman, dynamic Huffman) across compression
levels 0-9 and strategies (default, filtered, huffman-only, RLE, fixed), inputs from empty to
200 KB (random bytes to 70 KB) (text, repeated, random, sitemap XML), gzip header variants (name, comment, extra field,
header CRC), concatenated members, and malformed streams (truncated at several points, flipped
bits, wrong CRC, wrong length, bad method). The expectation for a valid case is the output's
SHA-256 and length; for a malformed one, that it must fail. For the malformed ones the fixture
also records what Scrapy's gunzip returns (partial output vs error) when scrapy is importable.
Deterministic: seeded generator, mtime fixed. BENCHMARK_MEASUREMENT: crafted streams.
"""
import gzip, hashlib, json, random, struct, sys, zlib

rnd = random.Random(20261008)


def sample(kind, n):
    if kind == "text":
        words = ["matcha", "whisk", "bamboo", "price", "JPY", "https://shop.example/p/", "<loc>", "</loc>", "item", "2026-10-08"]
        return " ".join(rnd.choice(words) for _ in range(n // 6 + 1)).encode()[:n]
    if kind == "repeat":
        return (b"abcabcabd" * (n // 9 + 1))[:n]
    if kind == "random":
        return bytes(rnd.getrandbits(8) for _ in range(n))
    if kind == "zeros":
        return b"\0" * n
    if kind == "sitemap":
        rows = "".join(f"<url><loc>https://shop.example/p/{i}</loc><lastmod>2026-09-{i % 28 + 1:02d}</lastmod></url>\n" for i in range(n // 90 + 1))
        return (f'<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n{rows}</urlset>\n').encode()[:n] if n < 200 else (f'<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n{rows}</urlset>\n').encode()
    raise ValueError(kind)


def member(data, level=9, strategy=zlib.Z_DEFAULT_STRATEGY, name=None, comment=None, extra=None, hcrc=False):
    flg = (2 if hcrc else 0) | (4 if extra is not None else 0) | (8 if name else 0) | (16 if comment else 0)
    head = struct.pack("<BBBBIBB", 0x1F, 0x8B, 8, flg, 0, 0, 255)
    if extra is not None:
        head += struct.pack("<H", len(extra)) + extra
    if name:
        head += name.encode() + b"\0"
    if comment:
        head += comment.encode() + b"\0"
    if hcrc:
        head += struct.pack("<H", zlib.crc32(head) & 0xFFFF)
    c = zlib.compressobj(level, zlib.DEFLATED, -15, 9, strategy)
    body = c.compress(data) + c.flush()
    return head + body + struct.pack("<II", zlib.crc32(data), len(data) & 0xFFFFFFFF)


cases = []


def add(name, blob, expect, **kw):
    cases.append({"name": name, "gz": blob.hex(), **expect, **kw})


def ok(data):
    return {"valid": True, "sha256": hashlib.sha256(data).hexdigest(), "length": len(data)}


strategies = {"default": zlib.Z_DEFAULT_STRATEGY, "filtered": zlib.Z_FILTERED, "huffman": zlib.Z_HUFFMAN_ONLY, "rle": zlib.Z_RLE, "fixed": zlib.Z_FIXED}
for kind in ["text", "repeat", "random", "zeros", "sitemap"]:
    for n in [0, 1, 7, 300, 4000, 70000, 200000]:
        if kind == "sitemap" and n in (0, 1, 7):
            continue
        d = sample(kind, n)
        for level in [0, 1, 6, 9]:
            for sname, strat in strategies.items():
                if sname != "default" and level not in (1, 9):
                    continue
                if n >= 70000 and (level not in (1, 9) or sname not in ("default", "fixed")):
                    continue
                # Incompressible bytes cost their full size in hex: keep a few small ones, and one
                # large stored/dynamic mix at level 6 added below.
                if kind == "random" and n >= 70000:
                    continue
                add(f"{kind}-{n}-L{level}-{sname}", member(d, level, strat), ok(d))
big_random = sample("random", 70000)
add("random-70000-L6-default", member(big_random, 6), ok(big_random))
d = sample("sitemap", 5000)
add("header-name-comment-extra-hcrc", member(d, 9, name="sitemap.xml", comment="made for the test", extra=b"\x01\x02\x03\x04", hcrc=True), ok(d))
add("header-extra-only", member(d, 6, extra=b"AB\x02\x00xy"), ok(d))
a, b = sample("text", 3000), sample("repeat", 2000)
add("two-members", member(a) + member(b), ok(a + b))
add("zero-padding", member(a) + b"\0" * 7, ok(a))
valid = member(sample("text", 6000), 9)
for cut in [3, 9, 11, 20, len(valid) // 2, len(valid) - 9, len(valid) - 8, len(valid) - 1]:
    add(f"truncated-at-{cut}", valid[:cut], {"valid": False})
for pos in [12, len(valid) // 3, len(valid) // 2, len(valid) - 12]:
    blob = bytearray(valid); blob[pos] ^= 0x10
    add(f"bit-flip-at-{pos}", bytes(blob), {"valid": False})
blob = bytearray(valid); blob[-8] ^= 1
add("wrong-crc", bytes(blob), {"valid": False})
blob = bytearray(valid); blob[-1] ^= 1
add("wrong-length", bytes(blob), {"valid": False})
blob = bytearray(valid); blob[2] = 7
add("bad-method", bytes(blob), {"valid": False})
add("trailing-junk", valid + b"junk", {"valid": False})
add("not-gzip", b"<?xml version='1.0'?><urlset/>", {"valid": False})
bomb = member(b"\0" * (64 * 1024 * 1024), 9)
add("bomb-64MiB-of-zeros", bomb, ok(b"\0" * (64 * 1024 * 1024)), bomb=True)

scrapy_partial = None
try:
    from scrapy.utils._compression import gunzip as scrapy_gunzip
    scrapy_partial = {}
    for c in cases:
        if c.get("bomb"):
            continue
        if not c["valid"]:
            try:
                out = scrapy_gunzip(bytes.fromhex(c["gz"]))
                c["scrapy"] = {"returned_bytes": len(out)}
            except Exception as e:  # noqa: BLE001
                c["scrapy"] = {"error": type(e).__name__}
except ImportError:
    pass
print(json.dumps({"class": "BENCHMARK_MEASUREMENT_NOT_ECDEV_RUNTIME_CAPTURE", "oracle": "CPython zlib/gzip (reference implementation)", "python": sys.version.split()[0],
                  "zlib": zlib.ZLIB_VERSION, "scrapy_commit": "54f7ed9cccbe19db3fe6cd2252bf3c29326c67d7", "cases": cases}))

#!/usr/bin/env python3
"""Freeze Scrapy's request identity on rewritten real URLs, to measure ECDEV against it.

Usage: <python with the pinned scrapy installed> scrapy_url_identity_oracle.py <urls.json> > fixture.json
urls.json is a list of public URLs from live captures (links in posts, kept outside the repository);
profile and social-network URLs are dropped. Each URL is rewritten in ways that change how a URL is
written but, by the URL standards, not what it names (query order, host case, default port,
fragment, percent-escape case, dot segments, an extra tracking parameter, empty path, scheme case,
an escaped unreserved letter, repeated slashes, a bare trailing '?') and in ways that name something else (path case,
parameter value, parameter name). For each pair the fixture records whether scrapy.utils.request.
fingerprint (method GET, no body, fragments dropped) treats the two as one request. The Rust test
domain/commerce/tests/scrapy_url_identity.rs computes ECDEV's answer for the same pairs and pins
the comparison. BENCHMARK_MEASUREMENT on captures kept outside the repository; selection is
deterministic (sorted by SHA-256 of the URL, at most PER_KIND per kind).
"""
import hashlib, json, re, sys
from urllib.parse import urlsplit, urlunsplit

import scrapy, w3lib
from scrapy import Request
from scrapy.utils.request import fingerprint

PER_KIND = 40
SOCIAL = re.compile(r"(bsky\.|mastodon|/@|/profile/|x\.com/|twitter\.com/|t\.co/)", re.I)


def fp(u):
    return fingerprint(Request(u)).hex()


def split(u):
    return urlsplit(u)


def q_reverse(u):
    s = split(u)
    parts = s.query.split("&")
    return urlunsplit(s._replace(query="&".join(reversed(parts)))) if len(parts) > 1 else None


def host_upper(u):
    s = split(u)
    return urlunsplit(s._replace(netloc=s.netloc.upper())) if s.hostname and "@" not in s.netloc else None


def default_port(u):
    s = split(u)
    if s.port is not None or "@" in s.netloc or not s.hostname:
        return None
    return urlunsplit(s._replace(netloc=s.netloc + (":443" if s.scheme == "https" else ":80")))


def fragment_add(u):
    return u + "#reviews" if "#" not in u else None


def pct_hex_case(u):
    v = re.sub(r"%([0-9A-F]{2})", lambda m: "%" + m.group(1).lower(), u)
    return v if v != u else None


def dot_segment(u):
    s = split(u)
    if not s.path.startswith("/") or s.path == "/":
        return None
    return urlunsplit(s._replace(path="/./" + s.path.lstrip("/")))


def tracking_add(u):
    s = split(u)
    return urlunsplit(s._replace(query=(s.query + "&" if s.query else "") + "utm_source=x"))


def empty_path(u):
    s = split(u)
    return urlunsplit(s._replace(path="")) if s.path == "/" and not s.query else None


def scheme_upper(u):
    return "HTTP" + u[4:] if u.startswith("http://") else ("HTTPS" + u[5:] if u.startswith("https://") else None)


def escaped_unreserved(u):
    s = split(u)
    m = re.search(r"[a-z]", s.path)
    if not m:
        return None
    p = s.path[: m.start()] + "%{:02X}".format(ord(m.group(0))) + s.path[m.end():]
    return urlunsplit(s._replace(path=p))


def repeated_slash(u):
    s = split(u)
    return urlunsplit(s._replace(path=s.path.replace("/", "//", 1))) if s.path.count("/") >= 2 else None


def empty_query_marker(u):
    return u + "?" if "?" not in u and "#" not in u else None


def path_case(u):
    s = split(u)
    return urlunsplit(s._replace(path=s.path.swapcase())) if re.search(r"[A-Za-z]", s.path) else None


def value_change(u):
    s = split(u)
    return urlunsplit(s._replace(query=s.query + "0")) if re.search(r"=[^&]+$", s.query) else None


def name_change(u):
    s = split(u)
    return urlunsplit(s._replace(query="x" + s.query)) if "=" in s.query else None


SAME = [("query_order", q_reverse), ("host_case", host_upper), ("default_port", default_port),
        ("fragment_added", fragment_add), ("percent_hex_case", pct_hex_case), ("dot_segment", dot_segment),
        ("tracking_parameter_added", tracking_add), ("empty_path", empty_path), ("scheme_case", scheme_upper),
        ("escaped_unreserved_letter", escaped_unreserved), ("repeated_slash", repeated_slash), ("empty_query_marker", empty_query_marker)]
DIFFERENT = [("path_case", path_case), ("parameter_value_changed", value_change), ("parameter_name_changed", name_change)]

urls = [u for u in json.load(open(sys.argv[1])) if not SOCIAL.search(u) and len(u) < 400]
urls.sort(key=lambda u: hashlib.sha256(u.encode()).hexdigest())
cases = []
for kind, fn in SAME + DIFFERENT:
    n = 0
    for u in urls:
        v = fn(u)
        if v is None or v == u:
            continue
        cases.append({"kind": kind, "intent": "SAME_RESOURCE" if (kind, fn) in SAME else "DIFFERENT_RESOURCE", "a": u, "b": v, "scrapy_same": fp(u) == fp(v)})
        n += 1
        if n == PER_KIND:
            break
out = {"class": "BENCHMARK_MEASUREMENT_NOT_ECDEV_RUNTIME_CAPTURE", "oracle": "scrapy.utils.request.fingerprint(Request(url)), method GET, no body, fragments dropped",
       "scrapy_version": scrapy.__version__, "scrapy_commit": "54f7ed9cccbe19db3fe6cd2252bf3c29326c67d7", "w3lib_version": w3lib.__version__,
       "source_urls": len(urls), "per_kind_limit": PER_KIND, "cases": cases}
json.dump(out, sys.stdout, indent=0, ensure_ascii=False)
